def coordinate_circle(n):
 if n==4:
  origin=(65,255);scale=70;cx,cy,r=2,1,1;vertices=[(3,1,'A(3,1)'),(2,2,'B(2,2)'),(2,1,'C')];line=[(-.2,3.2),(3.3,-.3)];line_label=(148,300,'x+y−3=0');limits=(-.4,3.5,-.4,3.4)
 else:
  origin=(95,185);scale=42;cx,cy,r=1.5,-2,sqrt(13)/2;vertices=[(0,-1,'A(0,−1)'),(3,-3,'B(3,−3)'),(1.5,-2,'C(h,k)')];line=[(-1,-2.5),(3,3.5)];line_label=(132,64,'3x−2y−2=0');limits=(-1.4,4.6,-4.1,3.6)
 def xy(x,y):return(origin[0]+scale*x,origin[1]-scale*y)
 x0,x1,y0,y1=limits
 paths=[path([xy(x0,0),xy(x1,0)]),path([xy(0,y0),xy(0,y1)]),path(ellipse(*xy(cx,cy),r*scale,r*scale)),path([xy(*line[0]),xy(*line[1])])]
 labels=[(*xy(x1,0),'x'),(*xy(0,y1),'y'),(origin[0]-17,origin[1]+20,'O'),line_label]
 points=[]
 for x,y,t in vertices:
  a,b=xy(x,y);points.append({'x':a,'y':b});labels.append((a+5,b-9,t))
 if n==5:paths.append(path([xy(0,-1),xy(3,-3)],dash=True))
 return geometry('Figure 8.5' if n==4 else 'Figure 8.7','Exact source circle and points for Example '+str(n),paths,labels,points,size=(430,380))
def tangent_sketch():
 return geometry('Figure 8.6','Figure 8.6 — circle through A,B and a given tangent with perpendicular radius',[path(ellipse(245,155,95,95)),path([(245,155),(312.175144,222.175144)]),path([(245,289.350288),(379.350288,155)],dash=True)],[(303,77,'A(x₁,y₁)'),(99,92,'B(x₂,y₂)'),(207,147,'C(−g,−f)'),(278,198,'r'),(305,278,'ax+by+d=0')],points=[{'x':312.175144,'y':87.824856},{'x':167.181,'y':100.51},{'x':245,'y':155},{'x':312.175144,'y':222.175144}],size=(500,320))
PAGES=[page('113_page_2.jpg',218,[heading('Example 4'),paragraph('Find the equation of a circle which passes through the points A(3,1) and B(2,2) having its center on the line x+y−3 = 0.'),heading('Solution'),paragraph('The required equation of a circle is x²+y²+2gx+2fy+c = 0 (i), which passes through the two points A(3,1) and B(2,2) that gives a system of two linear equations:'),eq(r'10+6g+2f+c=0\ \Rightarrow\ 6g+2f+c=-10'),eq(r'8+4g+4f+c=0\ \Rightarrow\ 4g+4f+c=-8','ii'),paragraph('If the center (−g,−f) of the circle lies on the line x+y−3 = 0, then the equation becomes:'),eq(r'-g-f-3=0\ \Rightarrow\ g+f=-3','iii'),coordinate_circle(4),paragraph('The combination of equations (ii) and (iii) is giving the system of three linear equations in three unknown g,f and c:'),product([[[6,2,1],[4,4,1],[1,1,0]],[['g'],['f'],['c']],[[-10],[-8],[-3]]],['','='],suffix='Ax = b'),paragraph('whose augmented matrix is:'),product([[[6,2,1,-10],[4,4,1,-8],[1,1,0,-3]]],prefix='A|b ='),paragraph('Reduce this augmented matrix in an echelon form to obtain the unknowns g,f and c:'),product([[[6,2,1,-10],[0,'8/3','1/3','−4/3'],[0,'2/3','−1/6','−4/3']]],prefix='R',suffix='by R₂−(2/3)R₁, R₃−(1/6)R₁'),product([[[6,2,1,-10],[0,'8/3','1/3','−4/3'],[0,0,'−1/4',-1]]],prefix='R',suffix='by R₃−(1/4)R₂'),eq(r'6g+2f+c=-10,\quad\frac83f+\frac13c=-\frac43,\quad-\frac14c=-1','iv'),paragraph('Third equation of the system (iv) is giving c = 4 which is used in second and first equations to obtain the values of f = −1 and g = −2. The values of g = −2, f = −1 and c = 4 are used in equation (i) to obtain the required circle equation:'),eq(r'x^2+y^2-4x-2y+4=0')]),
 page('114_page_1.jpg',219,[heading('C. The equation of a circle passing through two points and equation of tangent at one of these points is known'),paragraph('Consider the general equation of a circle is given by'),eq(r'x^2+y^2+2gx+2fy+c=0','i'),paragraph('If the given circle is passing through two points, say, A(x₁,y₁) and B(x₂,y₂), then these points must satisfy the general equation of a circle. Now put these two points in the given equation of a circle, i.e.:'),eq(r'x_1^2+y_1^2+2gx_1+2fy_1+c=0','ii'),eq(r'x_2^2+y_2^2+2gx_2+2fy_2+c=0','iii'),tangent_sketch(),paragraph('Also the given straight line ax+by+d = 0 (iv) touches the circle at one point, as shown in the given diagram, and it is clear from the diagram that the distance of a given point from the center (−g,−f) must be equal to the radius of the circle.'),note('A specified point of tangency must lie on both the circle and the tangent line. The radius to that point must also be perpendicular to the tangent. Merely requiring the two given points to lie on a circle does not impose this perpendicularity.'),
 heading('Example 5'),paragraph('Find the equation of a circle which passes through the two points A(0,−1) and B(3,−3) and 3x−2y−2 = 0 is the tangent line on the circle at a point A(0,−1).'),heading('Solution'),paragraph('Let C(h,k) be the center of the required circle. If A(0,−1) and B(3,−3) are the two points lie on the circle, then the square of the distance from C to point A equals the square of the distance from C to B:'),eq(r'|CA|^2=|CB|^2,\quad CA=(h-0,k+1),CB=(h-3,k+3)'),eq(r'(h-0)^2+(k+1)^2=(h-3)^2+(k+3)^2'),eq(r'h^2+k^2+2k+1=h^2-6h+9+k^2+9+6k'),eq(r'6h-4k-17=0','i'),coordinate_circle(5),paragraph('The slope of CA is'),eq(r'm_1=\frac{-1-k}{0-h}=\frac{k+1}h'),paragraph('and the slope of the tangent line 3x−2y−2 = 0 is'),eq(r'-2y=-3x+2\ \Rightarrow\ y=\frac32x-1,\quad m_2=\frac32'),paragraph('If CA is perpendicular to the tangent line, then the product of their slopes equals −1:'),eq(r'\left(\frac{k+1}h\right)\left(\frac32\right)=-1','ii'),eq(r'3k+3=-2h\ \Rightarrow\ 2h+3k+3=0'),paragraph('The equations (i) and (ii) are solved to obtain the values of k = −2 and h = 3/2. The required circle with center (h,k) = (3/2,−2) and radius')]),
 page('114_page_2.jpg',220,[eq(r'r=|CA|=|CB|=\sqrt{4^2+(k+1)^2}=\sqrt{\frac94+1}=\frac{\sqrt{13}}2'),eq(r'(x-h)^2+(y-k)^2=r^2'),eq(r'\left(x-\frac32\right)^2+(y+2)^2=\frac{13}4\ \Rightarrow\ x^2+y^2-3x+4y+3=0'),note('The printed radius expression begins with 4² even though h = 3/2. Its subsequent 9/4+1 and final radius correctly use h². The displacement symbols CA and CB on the preceding page use the opposite coordinate direction, but their squared lengths are unchanged. A vector-dot-product perpendicularity check avoids division by h in the slope argument.'),
 heading('D. The equation of a circle passing through two points and touching a given line'),heading('Example 6'),paragraph('Find the equation of a circle which passes through the two points A(0,0) and B(4,0) and is touching a line 3x+4y+4 = 0.'),heading('Solution'),paragraph('Let C(h,k) be the center of the required circle. If A(0,0) and B(4,0) are the two points lie on the circle, then the radius of the circle from center C to point A equals the radius of the circle from center C to point B:'),eq(r'|CA|^2=|CB|^2,\quad CA=(0-4,0-1),CB=(4-h,0-k)'),eq(r'(\sqrt{h^2+k^2})^2=(\sqrt{(4-h)^2+k^2})^2'),eq(r'h^2+k^2=16+h^2-8h+k^2\ \Rightarrow\ 8h=16\ \Rightarrow\ h=2'),paragraph('The radius of the required circle is r = |CA| = √(4+k²) and the center is C(2,k). For the values of k, the perpendicular distance from the center (2,k) to the line 3x+4y+4 = 0 equals the radius of the circle:'),eq(r'\frac{3(2)+4(k)+4}{\sqrt{9+16}}=\sqrt{4+k^2}'),eq(r'\frac{4k+10}5=\sqrt{4+k^2}'),eq(r'4k+10=5\sqrt{4+k^2},\quad\mathrm{squaring\ both\ sides}'),eq(r'16k^2+100+80k=25(4+k^2)'),eq(r'-9k^2+80k=0\ \Rightarrow\ -k(9k-80)=0\ \Rightarrow\ k=0,k=\frac{80}9'),paragraph('The coordinates of the center are (2,0) and (2,80/9) and the radii are r = √(4+0) = 2 and'),eq(r'r=\sqrt{4+\frac{80^2}{9^2}}=\sqrt{\frac{6724}{81}}=\frac{82}9'),paragraph('The equations of the circles with the above centers and radii are the following:'),eq(r'(x-2)^2+y^2=4'),eq(r'(x-2)^2+\left(y+\frac{80}9\right)^2=\frac{6724}{81}'),note('The first printed displacement CA = (0−4,0−1) is inconsistent with C(h,k); the correct C-to-A vector is (−h,−k). The following squared-distance equation does use h,k correctly. Geometric point-to-line distance requires |4k+10|/5; both derived k values satisfy the positive branch used here. The second printed circle uses y+80/9, contradicting the center (2,80/9). Correct it to y−80/9 in the learning answer and verify the original points and tangency. Squared equations alone must be checked against the original distance condition.')])]
for p in PAGES:
 p.update(title='CONICS-I',visualStatus='Complete center-on-line and tangent constructions, native matrices and exact source coordinate figures',alternateVerification={'pdf':'Math Book for 12 class KPTBB.pdf','pdfPage':113 if p['page']==218 else 114,'side':'left' if p['page']==219 else 'right','reason':'Enlarged source radius 4², malformed CA coordinates and incorrect final plus sign checked'})
EXAMPLES=[]
for n,q,steps,ans,start,end in [
 ('4','Find the circle through A(3,1), B(2,2), with center on x+y−3 = 0.',['Let the center be (h,k). Equidistance from the two points gives (3−h)²+(1−k)² = (2−h)²+(2−k)².','Expand and simplify: 2h−2k = 2, so h−k = 1.','The center lies on the given line, so h+k = 3.','Solving gives h = 2 and k = 1.','The squared radius is (3−2)²+(1−1)² = 1, giving (x−2)²+(y−1)² = 1.','Expand to x²+y²−4x−2y+4 = 0. Both given points give zero, and the center satisfies 2+1−3 = 0.'],'(x−2)²+(y−1)² = 1; center (2,1), radius 1.',218,218),
 ('5','Find the circle through A(0,−1), B(3,−3), tangent to 3x−2y−2 = 0 at A.',['First check that A lies on the proposed tangent: 0−2(−1)−2 = 0.','For center C(h,k), equidistance from A and B gives 6h−4k−17 = 0.','A tangent direction is (2,3). The radius vector C−A = (h,k+1) must be perpendicular, so 2h+3(k+1) = 0.','Solve 6h−4k = 17 and 2h+3k = −3 to get k = −2, h = 3/2.','Then r² = (3/2)²+(−2+1)² = 9/4+1 = 13/4.','The circle is (x−3/2)²+(y+2)² = 13/4, or x²+y²−3x+4y+3 = 0.','Both A and B give zero in the expanded equation. The radius dot tangent is 2(3/2)+3(−1) = 0, independently verifying tangency at A.'],'(x−3/2)²+(y+2)² = 13/4.',219,220),
 ('6','Find every circle through A(0,0), B(4,0), tangent to 3x+4y+4 = 0.',['A center equidistant from A and B lies on their perpendicular bisector: h = 2.','Write C = (2,k). Its squared radius is 4+k².','Tangency requires the geometric distance |3·2+4k+4|/5 to equal √(4+k²).','Square: (4k+10)² = 25(4+k²), giving k(9k−80) = 0.','Thus k = 0 or k = 80/9, with radii 2 and 82/9. Both give 4k+10 > 0 and satisfy the original distance equation.','The circles are (x−2)²+y² = 4 and (x−2)²+(y−80/9)² = 6724/81.','For each circle, A and B have squared center-distance 4+k², so both are on its circumference.','The perpendicular feet on the line are (4/5,−8/5) and (−52/15,8/5). Each foot lies on the line and its own circle, confirming a single tangency point. The source’s second final plus sign is corrected explicitly.'],'(x−2)²+y² = 4 and (x−2)²+(y−80/9)² = 6724/81.',220,220)]:
 EXAMPLES.append({'num':n,'title':'Circle Construction','question':q,'steps':steps,'answer':ans,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':start,'pageEnd':end,'jpg':'113_page_2.jpg' if start==218 else '114_page_1.jpg' if start==219 else '114_page_2.jpg','verification':'Full source construction and continuation visually checked'}],**({'sourceQuestionBlocks':[coordinate_circle(int(n))]} if n!='6' else {})})
